from ReasonData import DATA_DIR, ROS_ENV, Preference, Settings, logger

DEFAULT_STALE_PROCESS_GRACE_S = 2.0


def _local_sllidar_setup() -> Path | None:
    """Return the project-local SLLidar setup generated by colcon, if present."""
    configured = os.environ.get("SLLIDAR_ROS_SETUP")
    candidates = []
    if configured:
        candidates.append(Path(os.path.expanduser(configured)))
    candidates.append(
        Path(__file__).resolve().parents[2]
        / "src"
        / "ROS2_Nodes"
        / "sllidarROS"
        / "install"
        / "setup.bash"
    )
    for candidate in candidates:
        if candidate.is_file():
            return candidate
    return None


def _add_ros_python_path() -> None:
    if not ROS_ENV:
        return
    setup_path = Path(os.path.expanduser(str(ROS_ENV)))
    ros_root = setup_path.parent
    python_dir = f"python{sys.version_info.major}.{sys.version_info.minor}"
    site_packages = (
        ros_root / "lib" / python_dir / "site-packages",
        ros_root / "local" / "lib" / python_dir / "dist-packages",
    )
    for site_package in site_packages:
        if site_package.exists() and str(site_package) not in sys.path:
            sys.path.append(str(site_package))

    library_paths = [
        ros_root / "lib",
        ros_root / "lib" / f"{platform.machine()}-linux-gnu",
        ros_root / "opt" / "rviz_ogre_vendor" / "lib",
    ]
    current_library_path = os.environ.get("LD_LIBRARY_PATH", "").split(":")
    for library_path in reversed(library_paths):
        if library_path.is_dir() and str(library_path) not in current_library_path:
            current_library_path.insert(0, str(library_path))
    os.environ["LD_LIBRARY_PATH"] = ":".join(path for path in current_library_path if path)


